import { createClient } from '@libsql/client/sqlite3';
import { strict as assert } from 'node:assert';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { OnlineStateStorage } from '@raceiq/online/state-storage';
import { createRaceIqOnlineService } from '@raceiq/online/service';
import { enqueueOutboxJob, listDeliverableOutboxJobs, beginOutboxAttempt, recordOutboxAcceptance, settleOutboxDelivery } from '@raceiq/online/outbox-storage';
const dir = mkdtempSync(join(tmpdir(), 'raceiq-queue-status-'));
process.env.DATA_DIR = dir;
const storage = new OnlineStateStorage(dir);
const persisted = storage.load();
persisted.profile = { userId: 'queue-owner', displayName: 'Queue Driver', avatarUrl: null };
storage.save(persisted);
const create = () => createRaceIqOnlineService({ storage: new OnlineStateStorage(dir), keystore: { getSecret: async () => '', setSecret: async () => {} }, adapter: { getPolicy: async () => ({ available: true, termsVersion: 'terms-1', privacyVersion: 'privacy-1', termsUrl: 'https://example.com/terms', privacyUrl: 'https://example.com/privacy' }) } });
try {
  const service = create();
  const state = await service.getState();
  const identity = { accountId: 'queue-owner', accountEpoch: state.accountEpoch };
  await enqueueOutboxJob({ ...identity, gameId: 'acc', trackId: 'track-a', carId: 'car-a', lapId: 1, lapTimeMs: 90000 }, 1000);
  assert.equal((await service.getState()).sync.queued, 1, 'Online state must expose real durable pending work');
  const first = (await listDeliverableOutboxJobs(identity.accountId)).find(job => job.lapId === 1);
  assert.ok(first?.uploadKey);
  const job = await beginOutboxAttempt({ ...identity, rowId: first.rowId, uploadKey: first.uploadKey, attempts: 1 });
  assert.ok(job);
  assert.equal((await service.getState()).sync.inFlight, 1);
  assert.equal(await recordOutboxAcceptance(job, 'accepted-status-fixture', 3000), true);
  const timestamp = new Date(3000).toISOString();
  assert.equal((await service.getState()).sync.lastSyncedAt, timestamp);
  assert.equal((await service.getState()).sync.lastSyncedAt, timestamp, 'state refresh must not advance successful transfer time');
  await enqueueOutboxJob({ ...identity, gameId: 'acc', trackId: 'track-b', carId: 'car-a', lapId: 2, lapTimeMs: 80000 }, 4000);
  const second = (await listDeliverableOutboxJobs(identity.accountId)).find(job => job.lapId === 2);
  assert.ok(second?.uploadKey);
  const failed = await beginOutboxAttempt({ ...identity, rowId: second.rowId, uploadKey: second.uploadKey, attempts: 1 });
  assert.ok(failed);
  await settleOutboxDelivery({ job: failed, status: 'rejected', errorCode: 'validation_rejected', now: 6000 });
  const rejected = await service.getState();
  assert.equal(rejected.sync.rejected, 1);
  assert.equal(rejected.sync.lastError?.code, 'validation_rejected');
  assert.equal(rejected.sync.lastSyncedAt, timestamp, 'failed transfer must not advance timestamp');
  await enqueueOutboxJob({ ...identity, gameId: 'acc', trackId: 'track-c', carId: 'car-a', lapId: 3, lapTimeMs: 70000 }, 7000);
  const restored = await create().getState();
  assert.notEqual(restored.accountEpoch, identity.accountEpoch);
  assert.equal(restored.sync.queued, 1, 'authorization epoch rotation must not erase account-owned queue display');
  assert.equal(restored.sync.lastSyncedAt, timestamp, 'service restart must retain last successful transfer');
  const child = Bun.spawn([Bun.which('bun') ?? 'bun', fileURLToPath(new URL('./online-queue-status-restart-smoke.ts', import.meta.url)), dir], { stdout: 'pipe', stderr: 'pipe' });
  const [exitCode, stdout, stderr] = await Promise.all([child.exited, new Response(child.stdout).text(), new Response(child.stderr).text()]);
  assert.equal(exitCode, 0, stderr);
  const restarted = JSON.parse(stdout);
  assert.equal(restarted.sync.queued, 1, 'fresh process must see pending account-owned work');
  assert.equal(restarted.sync.lastSyncedAt, timestamp, 'fresh process must preserve successful upload timestamp');
  const other = storage.load();
  other.profile = { userId: 'another-owner', displayName: 'Other Driver', avatarUrl: null };
  storage.save(other);
  const switched = await create().getState();
  assert.equal(switched.sync.queued, 0);
  assert.equal(switched.sync.lastSyncedAt, null);
  assert.equal(switched.sync.lastError, null);
  const database = createClient({ url: `file:${join(dir, 'raceiq-online-outbox.db')}` });
  await database.execute('DROP TABLE raceiq_online_outbox');
  database.close();
  await assert.rejects(service.getState(), Error, 'storage failure must not fabricate an empty queue snapshot');
  console.log('Queue status: durable counts, acceptance/failure timestamps, restart, and account isolation passed.');
} finally { rmSync(dir, { recursive: true, force: true }); }
